import { useState, useEffect, useCallback } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer,
} from "recharts";

const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000";

async function api(path) {
  const res = await fetch(`${BASE_URL}${path}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function qs(params = {}) {
  const p = Object.fromEntries(
    Object.entries(params).filter(([, v]) => v !== null && v !== undefined && v !== "")
  );
  const s = new URLSearchParams(p).toString();
  return s ? "?" + s : "";
}

// ── SKU colours — consistent across all charts ────────────────────────────────
const SKU_COLORS = [
  "#378ADD", "#F97316", "#10B981", "#8B5CF6",
  "#F59E0B", "#EC4899", "#06B6D4", "#84CC16",
  "#EF4444", "#A78BFA", "#34D399", "#FCD34D",
];
function skuColor(sku, skuList) {
  return SKU_COLORS[skuList.indexOf(sku) % SKU_COLORS.length];
}

// Shorten SKU labels for legend / tooltip
function shortSku(name) {
  return name.replace(/SVASTHYAA\s*/i, "").trim();
}

function friendlyStore(store) {
  return (store.store_name || store.store_code || "Unknown Store").trim();
}

const MONTH_ORDER = [
  "January","February","March","April","May","June",
  "July","August","September","October","November","December",
];
const MONTHS_SHORT = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

function monthLabel(month, year) {
  const idx = MONTH_ORDER.indexOf(month);
  return idx >= 0 ? `${MONTHS_SHORT[idx]} '${String(year).slice(2)}` : `${month} ${year}`;
}

// ── Shared tooltip ────────────────────────────────────────────────────────────
function ChartTooltip({ active, payload, label, formatter }) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background: "var(--color-background-primary)",
      border: "0.5px solid var(--color-border-secondary)",
      borderRadius: "var(--border-radius-md)",
      padding: "8px 12px",
      fontSize: 13,
      minWidth: 160,
    }}>
      <p style={{ margin: "0 0 6px", fontWeight: 500, color: "var(--color-text-primary)" }}>
        {label}
      </p>
      {payload.map((entry) => (
        <p key={entry.dataKey} style={{ margin: "2px 0", color: "var(--color-text-secondary)", fontSize: 12 }}>
          <span style={{ color: entry.fill, fontWeight: 600 }}>●</span>{" "}
          {shortSku(entry.dataKey)}: {formatter ? formatter(entry.value) : entry.value}
        </p>
      ))}
    </div>
  );
}

// ── Skeleton loader ───────────────────────────────────────────────────────────
function Skeleton() {
  return (
    <div style={{ height: 180, background: "var(--color-background-secondary)", borderRadius: 8 }} />
  );
}

// ── Stacked bar chart (revenue / qty — X axis = month) ───────────────────────
function StackedChart({ title, data, valueKey, formatter, skuList, isLoading }) {
  // Pivot rows → [{month_year, label, SKU1: val, SKU2: val, _sort}]
  const pivotMap = {};
  (data || []).forEach(r => {
    const key = `${r.month} ${r.year}`;
    if (!pivotMap[key]) {
      pivotMap[key] = {
        month_year: key,
        label: monthLabel(r.month, r.year),
        _sort: r.year * 100 + (MONTH_ORDER.indexOf(r.month) + 1),
      };
    }
    pivotMap[key][r.sku_name] = (pivotMap[key][r.sku_name] || 0) + (r[valueKey] || 0);
  });
  const chartData = Object.values(pivotMap).sort((a, b) => a._sort - b._sort);

  return (
    <div style={styles.card}>
      <p style={styles.cardTitle}>{title}</p>
      {isLoading ? <Skeleton /> : chartData.length === 0 ? (
        <p style={styles.empty}>No data for selected filters</p>
      ) : (
        <ResponsiveContainer width="100%" height={200}>
          <BarChart data={chartData} margin={{ top: 4, right: 16, left: 0, bottom: 0 }}>
            <CartesianGrid vertical={false} stroke="var(--color-border-tertiary)" strokeDasharray="4 4" />
            <XAxis
              dataKey="label"
              tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
              tickFormatter={formatter}
              axisLine={false}
              tickLine={false}
              width={52}
            />
            <Tooltip
              content={<ChartTooltip formatter={formatter} />}
              cursor={{ fill: "var(--color-background-secondary)", opacity: 0.5 }}
            />
            <Legend
              wrapperStyle={{ fontSize: 11, color: "var(--color-text-tertiary)", paddingTop: 12 }}
              formatter={shortSku}
            />
            {skuList.map(sku => (
              <Bar key={sku} dataKey={sku} stackId="a" fill={skuColor(sku, skuList)} radius={0} maxBarSize={40} />
            ))}
          </BarChart>
        </ResponsiveContainer>
      )}
    </div>
  );
}

// ── SOH chart (X axis = store) ────────────────────────────────────────────────
function SohChart({ data, skuList, isLoading }) {
  const pivotMap = {};
  (data || []).forEach(r => {
    const key = friendlyStore(r);
    if (!pivotMap[key]) pivotMap[key] = { store: key };
    pivotMap[key][r.sku_name] = (pivotMap[key][r.sku_name] || 0) + (r.soh_qty || 0);
  });
  const chartData = Object.values(pivotMap);

  return (
    <div style={styles.card}>
      <p style={styles.cardTitle}>Stock on Hand</p>
      <p style={styles.cardSub}>Current units per store — latest upload</p>
      {isLoading ? <Skeleton /> : chartData.length === 0 ? (
        <p style={styles.empty}>No SOH data available</p>
      ) : (
        <ResponsiveContainer width="100%" height={200}>
          <BarChart data={chartData} margin={{ top: 4, right: 16, left: 0, bottom: 0 }}>
            <CartesianGrid vertical={false} stroke="var(--color-border-tertiary)" strokeDasharray="4 4" />
            <XAxis
              dataKey="store"
              tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
              axisLine={false}
              tickLine={false}
              width={40}
            />
            <Tooltip
              content={<ChartTooltip formatter={v => `${v} units`} />}
              cursor={{ fill: "var(--color-background-secondary)", opacity: 0.5 }}
            />
            <Legend
              wrapperStyle={{ fontSize: 11, color: "var(--color-text-tertiary)", paddingTop: 12 }}
              formatter={shortSku}
            />
            {skuList.map(sku => (
              <Bar key={sku} dataKey={sku} stackId="a" fill={skuColor(sku, skuList)} radius={0} maxBarSize={60} />
            ))}
          </BarChart>
        </ResponsiveContainer>
      )}
    </div>
  );
}

// ── KPI strip ─────────────────────────────────────────────────────────────────
function KpiStrip({ revenueData, qtyData, sohData }) {
  const totalRev = revenueData.reduce((s, r) => s + (r.total_revenue || 0), 0);
  const totalQty = qtyData.reduce((s, r) => s + (r.total_qty || 0), 0);
  const totalSoh = sohData.reduce((s, r) => s + (r.soh_qty || 0), 0);
  const kpis = [
    { label: "Total Revenue",  value: `₹${(totalRev / 1000).toFixed(1)}K`, icon: "ti-currency-rupee" },
    { label: "Units Sold",     value: totalQty.toLocaleString(),            icon: "ti-package" },
    { label: "Units in Stock", value: totalSoh.toLocaleString(),            icon: "ti-stack" },
  ];
  return (
    <div style={styles.kpiRow}>
      {kpis.map(k => (
        <div key={k.label} style={styles.kpiCard}>
          <i className={`ti ${k.icon}`} style={styles.kpiIcon} aria-hidden />
          <p style={styles.kpiValue}>{k.value}</p>
          <p style={styles.kpiLabel}>{k.label}</p>
        </div>
      ))}
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────
export default function ModernTradeAnalytics() {
  const [chains, setChains] = useState([]);
  const [stores, setStores] = useState([]);
  const [months, setMonths] = useState([]);
  const [skus,   setSkus]   = useState([]);

  const [selChain, setSelChain] = useState("");
  const [selStore, setSelStore] = useState("");
  const [selMonth, setSelMonth] = useState("");
  const [selYear,  setSelYear]  = useState("");
  const [selSku,   setSelSku]   = useState("");

  const [revenueData, setRevenueData] = useState([]);
  const [qtyData,     setQtyData]     = useState([]);
  const [sohData,     setSohData]     = useState([]);

  const [loadingChains, setLoadingChains] = useState(true);
  const [loadingCharts, setLoadingCharts] = useState(false);

  const allSkus = [...new Set([
    ...revenueData.map(r => r.sku_name),
    ...qtyData.map(r => r.sku_name),
    ...sohData.map(r => r.sku_name),
  ])].sort();

  useEffect(() => {
    api("/mt/chains")
      .then(setChains).catch(console.error)
      .finally(() => setLoadingChains(false));
  }, []);

  useEffect(() => {
    if (!selChain) {
      setStores([]); setMonths([]); setSkus([]);
      setSelStore(""); setSelMonth(""); setSelYear(""); setSelSku("");
      return;
    }
    Promise.all([
      api(`/mt/analytics/stores${qs({ chain: selChain })}`),
      api(`/mt/analytics/months${qs({ chain: selChain })}`),
      api(`/mt/analytics/skus${qs({ chain: selChain })}`),
    ]).then(([s, m, k]) => {
      setStores(s); setMonths(m); setSkus(k);
      setSelStore(""); setSelMonth(""); setSelYear(""); setSelSku("");
    }).catch(console.error);
  }, [selChain]);

  const loadCharts = useCallback(() => {
    const params = {
      chain:      selChain || undefined,
      store_code: selStore || undefined,
      month:      selMonth || undefined,
      year:       selYear  || undefined,
      sku:        selSku   || undefined,
    };
    setLoadingCharts(true);
    Promise.all([
      api(`/mt/analytics/revenue${qs(params)}`),
      api(`/mt/analytics/qty${qs(params)}`),
      api(`/mt/analytics/soh${qs({ chain: params.chain, store_code: params.store_code, sku: params.sku })}`),
    ]).then(([rev, qty, soh]) => {
      setRevenueData(rev); setQtyData(qty); setSohData(soh);
    }).catch(console.error)
      .finally(() => setLoadingCharts(false));
  }, [selChain, selStore, selMonth, selYear, selSku]);

  useEffect(() => { loadCharts(); }, [loadCharts]);

  const years          = [...new Set(months.map(m => m.year))].sort();
  const monthsFiltered = selYear ? months.filter(m => String(m.year) === String(selYear)) : months;
  const visibleStores  = stores; // already scoped to selChain by the API

  if (loadingChains) {
    return (
      <div style={styles.page}>
        <p style={{ color: "var(--color-text-tertiary)", fontSize: 14 }}>Loading…</p>
      </div>
    );
  }

  const hasData = revenueData.length > 0 || sohData.length > 0;

  return (
    <div style={styles.page}>

      {/* Header */}
      <div style={styles.header}>
        <p style={styles.h1}>Modern Trade Analytics</p>
        <p style={styles.subtitle}>
          {selChain
            ? `${selChain} · ${visibleStores.length} store${visibleStores.length !== 1 ? "s" : ""}`
            : "Select a chain to begin"}
        </p>
      </div>

      {/* Filter bar */}
      <div style={styles.filterBar}>
        {[
          {
            label: "Chain", value: selChain,
            onChange: e => setSelChain(e.target.value),
            disabled: false,
            options: chains.map(c => ({ value: c.chain_name, label: c.chain_name })),
            placeholder: "All Chains",
          },
          {
            label: "Store", value: selStore,
            onChange: e => setSelStore(e.target.value),
            disabled: !selChain,
            options: visibleStores.map(s => ({ value: s.store_code, label: friendlyStore(s) })),
            placeholder: "All Stores",
          },
          {
            label: "Year", value: selYear,
            onChange: e => { setSelYear(e.target.value); setSelMonth(""); },
            disabled: !selChain,
            options: years.map(y => ({ value: y, label: y })),
            placeholder: "All Years",
          },
          {
            label: "Month", value: selMonth,
            onChange: e => setSelMonth(e.target.value),
            disabled: !selChain,
            options: monthsFiltered.map(m => ({ value: m.month, label: `${m.month} ${m.year}` })),
            placeholder: "All Months",
          },
          {
            label: "SKU", value: selSku,
            onChange: e => setSelSku(e.target.value),
            disabled: !selChain,
            options: skus.map(s => ({ value: s.sku_name, label: shortSku(s.sku_name) })),
            placeholder: "All SKUs",
          },
        ].map(f => (
          <div key={f.label} style={styles.filterGroup}>
            <label style={styles.filterLabel}>{f.label}</label>
            <select style={{ ...styles.select, opacity: f.disabled ? 0.45 : 1 }}
              value={f.value} onChange={f.onChange} disabled={f.disabled}>
              <option value="">{f.placeholder}</option>
              {f.options.map(o => (
                <option key={o.value} value={o.value}>{o.label}</option>
              ))}
            </select>
          </div>
        ))}

        {(selChain || selStore || selMonth || selYear || selSku) && (
          <button style={styles.resetBtn}
            onClick={() => { setSelChain(""); setSelStore(""); setSelMonth(""); setSelYear(""); setSelSku(""); }}>
            <i className="ti ti-x" style={{ fontSize: 12 }} /> Reset
          </button>
        )}
      </div>

      {/* Store chips — drill-down when chain is selected */}
      {selChain && visibleStores.length > 1 && (
        <div style={styles.chipRow}>
          <span style={styles.chipRowLabel}>Stores:</span>
          {visibleStores.map(s => (
            <button
              key={s.store_code}
              style={{ ...styles.chip, ...(selStore === s.store_code ? styles.chipActive : {}) }}
              onClick={() => setSelStore(selStore === s.store_code ? "" : s.store_code)}
            >
              {friendlyStore(s)}
            </button>
          ))}
        </div>
      )}

      {/* KPIs */}
      {!loadingCharts && hasData && (
        <KpiStrip revenueData={revenueData} qtyData={qtyData} sohData={sohData} />
      )}

      {/* Charts */}
      <div style={styles.charts}>
        <StackedChart
          title="Revenue by SKU"
          data={revenueData}
          valueKey="total_revenue"
          formatter={v => `₹${(v / 1000).toFixed(1)}k`}
          skuList={allSkus}
          isLoading={loadingCharts}
        />
        <StackedChart
          title="Units Sold by SKU"
          data={qtyData}
          valueKey="total_qty"
          formatter={v => `${v}`}
          skuList={allSkus}
          isLoading={loadingCharts}
        />
        <SohChart data={sohData} skuList={allSkus} isLoading={loadingCharts} />
      </div>

      {/* Empty state */}
      {!loadingCharts && chains.length === 0 && (
        <div style={styles.emptyPage}>
          <i className="ti ti-building-store" style={{ fontSize: 40, color: "var(--color-text-tertiary)" }} />
          <p style={{ color: "var(--color-text-tertiary)", marginTop: 12, fontSize: 14 }}>
            No Modern Trade data yet. Upload an MT Excel file to get started.
          </p>
        </div>
      )}
    </div>
  );
}

// ── Styles — all CSS variables, matching MoMTrendChart ────────────────────────
const styles = {
  page: {
    padding: "1.5rem",
    minHeight: "100vh",
    background: "var(--color-background-tertiary)",
  },
  header: {
    marginBottom: "1.25rem",
  },
  h1: {
    margin: 0,
    fontSize: 15,
    fontWeight: 500,
    color: "var(--color-text-primary)",
  },
  subtitle: {
    margin: "2px 0 0",
    fontSize: 13,
    color: "var(--color-text-tertiary)",
  },

  // Filter bar
  filterBar: {
    display: "flex",
    flexWrap: "wrap",
    gap: 10,
    alignItems: "flex-end",
    marginBottom: "1rem",
    padding: "12px 14px",
    background: "var(--color-background-primary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: "var(--border-radius-lg)",
  },
  filterGroup: {
    display: "flex",
    flexDirection: "column",
    gap: 4,
    minWidth: 140,
  },
  filterLabel: {
    fontSize: 11,
    fontWeight: 500,
    color: "var(--color-text-tertiary)",
    textTransform: "uppercase",
    letterSpacing: "0.04em",
  },
  select: {
    padding: "5px 8px",
    borderRadius: "var(--border-radius-md)",
    border: "0.5px solid var(--color-border-secondary)",
    background: "var(--color-background-primary)",
    color: "var(--color-text-primary)",
    fontSize: 13,
    cursor: "pointer",
    outline: "none",
  },
  resetBtn: {
    alignSelf: "flex-end",
    padding: "5px 10px",
    borderRadius: "var(--border-radius-md)",
    border: "0.5px solid var(--color-border-secondary)",
    background: "transparent",
    color: "var(--color-text-tertiary)",
    fontSize: 12,
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    gap: 4,
  },

  // Store chips
  chipRow: {
    display: "flex",
    flexWrap: "wrap",
    gap: 6,
    alignItems: "center",
    marginBottom: "1rem",
  },
  chipRowLabel: {
    fontSize: 12,
    color: "var(--color-text-tertiary)",
    fontWeight: 500,
  },
  chip: {
    padding: "3px 10px",
    borderRadius: 20,
    border: "0.5px solid var(--color-border-secondary)",
    background: "var(--color-background-primary)",
    color: "var(--color-text-secondary)",
    fontSize: 12,
    cursor: "pointer",
  },
  chipActive: {
    background: "var(--color-text-info, #378ADD)",
    borderColor: "var(--color-text-info, #378ADD)",
    color: "#fff",
  },

  // KPI row
  kpiRow: {
    display: "grid",
    gridTemplateColumns: "repeat(3, 1fr)",
    gap: 10,
    marginBottom: "1rem",
  },
  kpiCard: {
    padding: "14px 16px",
    background: "var(--color-background-primary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: "var(--border-radius-lg)",
  },
  kpiIcon: {
    fontSize: 16,
    color: "var(--color-text-info, #378ADD)",
    display: "block",
    marginBottom: 6,
  },
  kpiValue: {
    margin: 0,
    fontSize: 20,
    fontWeight: 500,
    color: "var(--color-text-primary)",
    lineHeight: 1.2,
  },
  kpiLabel: {
    margin: "2px 0 0",
    fontSize: 12,
    color: "var(--color-text-tertiary)",
  },

  // Chart cards
  charts: {
    display: "flex",
    flexDirection: "column",
    gap: 14,
  },
  card: {
    padding: "1.25rem 1.5rem",
    background: "var(--color-background-primary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: "var(--border-radius-lg)",
  },
  cardTitle: {
    margin: "0 0 4px",
    fontWeight: 500,
    fontSize: 14,
    color: "var(--color-text-primary)",
  },
  cardSub: {
    margin: "0 0 12px",
    fontSize: 12,
    color: "var(--color-text-tertiary)",
  },
  empty: {
    textAlign: "center",
    color: "var(--color-text-tertiary)",
    padding: "2rem 0",
    margin: 0,
    fontSize: 13,
  },
  emptyPage: {
    textAlign: "center",
    paddingTop: 80,
  },
};
